import {sharedUi} from './app.js?v=5';
import {esc} from './core.js';
import {signIn,enroll,accountEmail,invitePartner,accountProfile,refreshAccountProfile} from './cloud-v2.js?v=5';
import {googleProviderEnabled,googleAuthorizationUrl,finishGoogleSignIn} from './google-auth.js?v=5';
let googleAvailable=false;
function access(){const token=location.hash.match(/^#convite=([a-f0-9]{64})$/)?.[1];return `<section class="access-layout"><div class="access-story"><div class="eyebrow"><span class="live-dot"></span> FEITO PARA VOCÊS DOIS</div><h1>O próximo capítulo<br>começa <span class="green">com um ping.</span></h1><p>Um espaço só de vocês para planejar destinos, acompanhar cotações e decidir a próxima viagem. Os mesmos planos, em qualquer aparelho.</p><div class="access-radar">${sharedUi.radarSvg()}</div><span class="badge">♡ DOIS VIAJANTES. MUITAS POSSIBILIDADES.</span></div><section class="panel access-form"><div class="eyebrow">NOSSO ESPAÇO</div><h2>${token?'Seu lugar na próxima viagem.':'Que bom ter você de volta.'}</h2><p>${token?'Ative seu convite e escolha sua senha.':'Entre para abrir os planos que vocês compartilham.'}</p><div id="google-access" ${googleAvailable?'':'hidden'}><button class="btn google-btn" type="button" data-google-login><span aria-hidden="true">G</span> Entrar com Google</button><div class="login-divider">ou use sua senha</div></div><form id="shared-access" data-token="${token||''}" class="stack"><div class="field"><label for="access-email">Seu e-mail</label><input id="access-email" name="email" type="email" autocomplete="username" required></div><div class="field"><label for="access-password">${token?'Escolha uma senha':'Sua senha'}</label><input id="access-password" name="password" type="password" minlength="${token?8:1}" maxlength="128" autocomplete="${token?'new-password':'current-password'}" required>${token?'<small>Use pelo menos 8 caracteres.</small>':''}</div>${token?'<div class="field"><label for="access-confirm">Repita a senha</label><input id="access-confirm" name="confirm" type="password" minlength="8" maxlength="128" autocomplete="new-password" required></div>':''}<button class="btn primary" type="submit">${token?'Ativar meu acesso':'Entrar no nosso espaço'} ↗</button><p id="access-error" class="modal-error" role="alert"></p></form><div class="hint">${token?'Este convite é privado, vale 7 dias e só funciona com o e-mail para o qual foi criado.':'O acesso é privado e por convite. Na primeira visita, use o link de ativação recebido do primeiro viajante.'}</div><p class="price-source">Seus planos são guardados no Supabase. Consultas automáticas de passagens ainda não estão conectadas.</p></section></section>`;}
function settings(){const s=sharedUi.state,st=sharedUi.status;return sharedUi.pageHeader('DO NOSSO JEITO','Pequenos ajustes. Grandes planos.','Os mesmos planos, no computador e nos celulares de vocês.')+`<div class="settings-grid"><section class="panel"><h2>Os dois viajantes</h2><p>Como vocês querem aparecer por aqui?</p><form id="profile-form" class="stack"><div class="field"><label for="nameA">Primeiro viajante</label><input id="nameA" name="nameA" value="${esc(s.settings.nameA)}" maxlength="40" required></div><div class="field"><label for="nameB">Segundo viajante</label><input id="nameB" name="nameB" value="${esc(s.settings.nameB)}" maxlength="40" required></div><button class="btn primary" type="submit">Salvar nossos nomes</button></form></section><section class="panel"><h2>Nosso espaço compartilhado</h2><div class="account-summary"><span class="avatar account-avatar" data-account-avatar></span><div><strong>${esc(accountProfile()?.name||'Viajante')}</strong><small>${esc(accountEmail())}</small></div></div><p>Os planos ficam no banco do casal, protegidos por login.</p><span class="badge">${st.conflict?'Há atualizações em outro aparelho':st.dirty?'Salvando alterações…':st.ready?'Conectado ao espaço do casal':'Conectando…'}</span><div class="toolbar" style="margin-top:20px"><button class="btn primary" data-action="sync">${st.conflict?'Carregar versão do casal':'Sincronizar agora'}</button><button class="btn ghost" data-action="logout">Sair deste aparelho</button></div><p class="price-source">Com o app aberto, as atualizações são conferidas a cada 30 segundos. Sem internet, mantenha o app aberto até conseguir sincronizar.</p></section><section class="panel"><h2>Um convite para viajar a dois</h2><p>O primeiro viajante pode liberar o e-mail do segundo. O convite é privado, vale 7 dias e só pode ser usado uma vez.</p><form id="shared-invite" class="stack"><div class="field"><label for="partner-email">E-mail do segundo viajante</label><input id="partner-email" name="email" type="email" placeholder="E-mail do seu amor" required autocomplete="email"></div><button class="btn primary" type="submit">Gerar convite privado ♡</button><p id="invite-error" class="modal-error" role="alert"></p></form><div id="invite-result" aria-live="polite"></div><p class="price-source">Copie o convite e envie você mesmo. Quem recebê-lo define a própria senha e acessa os mesmos radares. O app não envia mensagens.</p></section><section class="panel"><h2>Seus planos, com vocês</h2><p>Um backup extra para guardar com carinho.</p><div class="stack"><button class="btn ghost" data-action="export">↓ Exportar backup</button><button class="btn ghost" data-action="import">↑ Restaurar backup</button><input id="import-file" type="file" accept="application/json,.json" hidden><button class="btn ghost" data-action="notifications">♧ Notificações com o app aberto</button><button class="btn ghost" data-action="install">↗ Instalar AeroPing</button><button class="btn danger" data-action="reset">Apagar os planos do casal</button></div><div class="hint">GitHub Pages + Supabase Free. Nenhum serviço pago foi ativado. Consultas automáticas de passagens ainda não estão conectadas.</div></section></div>`;}
sharedUi.configure({access,settings});
document.addEventListener('submit',async e=>{const f=e.target;if(!['shared-access','shared-invite'].includes(f.id))return;e.preventDefault();const d=new FormData(f),b=f.querySelector('button[type=submit]'),error=document.querySelector(f.id==='shared-access'?'#access-error':'#invite-error');error.textContent='';b.disabled=true;try{const email=String(d.get('email')||'').trim().toLowerCase();if(f.id==='shared-access'){const password=String(d.get('password')||'');if(f.dataset.token){if(password!==d.get('confirm'))throw Error('As senhas precisam ser iguais.');await enroll(f.dataset.token,email,password);}else await signIn(email,password);f.reset();history.replaceState(null,'',location.pathname+location.search+'#radar');await sharedUi.loginReady();}else{const invite=await invitePartner(email),url=new URL(location.pathname,location.origin);url.hash='convite='+invite.token;document.querySelector('#invite-result').innerHTML=`<div class="hint"><strong>Convite pronto.</strong><p style="margin-top:8px">Envie de forma privada para ${esc(invite.email)}.</p><input id="invite-link" value="${esc(url.href)}" readonly aria-label="Link privado do convite" style="margin-top:12px"><button class="btn ghost" type="button" data-copy-invite style="margin-top:10px">Copiar convite</button></div>`;}}catch(err){error.textContent=err.message;}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('click',async e=>{if(!e.target.closest('[data-copy-invite]'))return;try{await navigator.clipboard.writeText(document.querySelector('#invite-link').value);sharedUi.toast('Convite copiado. Envie de forma privada.');}catch{sharedUi.toast('Selecione e copie o link do convite.');}});

async function revealGoogle(){googleAvailable=await googleProviderEnabled();const area=document.querySelector('#google-access');if(area)area.hidden=!googleAvailable;}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-google-login]');if(!button)return;button.disabled=true;try{location.assign(await googleAuthorizationUrl());}catch{button.disabled=false;sharedUi.toast('Não foi possível abrir o Google. Tente novamente.');}});
try{if(await finishGoogleSignIn())await sharedUi.loginReady();}catch(e){sharedUi.toast(e.message);}
revealGoogle();window.addEventListener('focus',revealGoogle);

refreshAccountProfile().then(()=>sharedUi.refreshPresentation()).catch(()=>{});
